def load_task_info(task_id: str) -> tuple[str, str, str, str]:
    """Returns (diff_str, pr_description, language, metadata_json)."""
    if not task_id:
        return "", "", "", "{}"
    try:
        task = _get_task(task_id)
        meta = {
            "task_id": task.task_id,
            "difficulty": task.difficulty,
            "repo_kind": task.repo_kind,
            "risk_domains": task.risk_domains,
            "changed_file_types": task.changed_file_types,
            "expected_verdict": task.expected_verdict,
            "review_goal": task.review_goal,
        }
        return (
            task.diff_str,
            task.pr_description,
            task.primary_language,
            json.dumps(meta, indent=2),
        )
    except KeyError:
        return "", "Task not found.", "", "{}"


def run_analysis(
    task_id: str,
    custom_diff: str,
    use_custom: bool,
    tools: list[str],
) -> tuple[str, str, str]:
    """Run selected tools + verdict. Returns (results_json, verdict_md, score_table_md)."""
    os.environ["PR_REVIEW_TOOL_BACKEND"] = "heuristic"

    from envs.pr_review_env.server.tools import TOOL_REGISTRY

    diff = custom_diff.strip() if use_custom else _get_diff(task_id)
    if not diff:
        return "{}", "_No diff provided._", "_No results._"

    results: dict[str, dict] = {}
    analysis_tools = [t for t in (tools or []) if t in TOOL_REGISTRY and t not in ("submit_review", "escalate")]

    for tool_name in analysis_tools:
        tool_fn = TOOL_REGISTRY[tool_name]
        try:
            result = tool_fn(diff)
            results[tool_name] = result if isinstance(result, dict) else {"raw": result}
        except Exception as exc:  # noqa: BLE001
            results[tool_name] = {"error": str(exc), "score": 0.5}

    # Build score table
    table_lines = ["| Tool | Score | Bar |", "|---|---|---|"]
    for tool_name in TOOL_NAMES:
        if tool_name in results:
            score = float(results[tool_name].get("score", 0.5))
            filled = int(round(score * 10))
            bar = "█" * filled + "░" * (10 - filled)
            table_lines.append(f"| `{tool_name}` | {score:.2f} | `{bar}` |")

    score_table_md = "\n".join(table_lines) if results else "_No tools selected._"

    # Build verdict
    scores = {name: float(payload.get("score", 1.0)) for name, payload in results.items()}
    security_score = scores.get("check_security", 1.0)
    config_score = scores.get("check_config", 1.0)
    quality_score = scores.get("check_quality", 1.0)
    build_score = scores.get("check_build_and_types", 1.0)
    tests_score = scores.get("check_tests", 1.0)
    min_score = min(scores.values(), default=1.0)

    if not scores:
        verdict = "unknown"
    elif security_score <= 0.55:
        verdict = "reject"
    elif (
        min_score <= 0.74
        or config_score <= 0.72
        or quality_score <= 0.68
        or build_score <= 0.7
        or tests_score <= 0.65
    ):
        verdict = "request_changes"
    else:
        verdict = "approve"

    mode_badge = "🔬 Heuristic Demo Mode"
    if CHECKPOINT_DIR.exists():
        mode_badge = "🤖 Model Mode (grpo_checkpoint found)"

    if verdict == "approve":
        verdict_md = f"**{mode_badge}**\n\n## Verdict\n\n**APPROVE** ✅"
    elif verdict == "reject":
        verdict_md = f"**{mode_badge}**\n\n## Verdict\n\n**REJECT** ❌"
    elif verdict == "request_changes":
        verdict_md = f"**{mode_badge}**\n\n## Verdict\n\n**REQUEST CHANGES** ⚠️"
    else:
        verdict_md = f"**{mode_badge}**\n\n## Verdict\n\n**UNKNOWN** (no tools run)"

    return json.dumps(results, indent=2), verdict_md, score_table_md


