def build_task_dataframe() -> list[dict]:
    """Return list of dicts for gr.Dataframe."""
    rows = []
    for task in _load_tasks_cached():
        rows.append(
            {
                "task_id": task.task_id,
                "language": task.primary_language,
                "file_types": ", ".join(task.changed_file_types),
                "verdict": task.expected_verdict,
                "difficulty": task.difficulty,
                "risk_domains": ", ".join(task.risk_domains) if task.risk_domains else "—",
            }
        )
    return rows


def show_task_detail(selected_task_id: str) -> tuple[str, str, str]:
    """Returns (diff_code, metadata_md, review_goal)."""
    if not selected_task_id:
        return "", "_Select a task._", ""
    try:
        task = _get_task(selected_task_id)
    except KeyError:
        return "", "_Task not found._", ""

    meta_md = f"""**Task ID:** `{task.task_id}`

**Language:** {task.primary_language}
**File types:** {", ".join(task.changed_file_types)}
**Repo kind:** {task.repo_kind}
**Difficulty:** {task.difficulty}
**Expected verdict:** `{task.expected_verdict}`
**Risk domains:** {", ".join(task.risk_domains) if task.risk_domains else "—"}
**Ownership hint:** {task.ownership_hint or "—"}

**PR Description:**
{task.pr_description}
"""
    return task.diff_str, meta_md, task.review_goal


def filter_tasks(
    language_filter: list[str],
    verdict_filter: list[str],
    difficulty_filter: list[str],
) -> list[list]:
    """Return filtered rows as list-of-lists for gr.Dataframe."""
    rows = []
    for task in _load_tasks_cached():
        if language_filter and task.primary_language not in language_filter:
            continue
        if verdict_filter and task.expected_verdict not in verdict_filter:
            continue
        if difficulty_filter and task.difficulty not in difficulty_filter:
            continue
        rows.append(
            [
                task.task_id,
                task.primary_language,
                ", ".join(task.changed_file_types),
                task.expected_verdict,
                task.difficulty,
                ", ".join(task.risk_domains) if task.risk_domains else "—",
            ]
        )
    return rows


# ---------------------------------------------------------------------------
# Derived data for dropdowns
# ---------------------------------------------------------------------------

def _all_languages() -> list[str]:
    langs = sorted({t.primary_language for t in _load_tasks_cached()})
    return langs


